using NUnit.Framework;
using AcadeGameMaker.Costumes;
using AcadeGameMaker.Presentation;
namespace AcadeGameMaker.Tests.EditMode.Presentation { public sealed class CostumePresentationV1Tests { const string H="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"; static CostumeDefinitionV1 D(string id,long r)=>new CostumeDefinitionV1("seryeong","seryeong.costume."+id+".v1",id,H,"hair",CostumeDisposition.Accepted,id=="one","seryeong.costume."+id+".v1.portrait.v1","seryeong.costume."+id+".v1.atlas.v1",H,H,H,r); [Test] public void AC_COST_005_DefaultBindingFailsClosed(){var binding=default(CostumePresentationBindingV1);Assert.That(binding.HasClip("seryeong.action.idle.v1"),Is.False);Assert.That(binding.ClipIds.Count,Is.EqualTo(0));} [Test] public void AC_COST_007_SwapValidatesEachCostumeNotGlobalRevision(){var a=D("one",10);var b=D("two",1);var c=new CostumeCatalogV1(1,new[]{a,b});CostumePresentationServiceV1.TryCreateBinding(c,"seryeong",a.CostumeId,1,10,new[]{"seryeong.action.idle.v1"},out var current);CostumePresentationServiceV1.TryCreateBinding(c,"seryeong",b.CostumeId,1,1,new[]{"seryeong.action.idle.v1"},out var proposed);var s=new CompletedActorSnapshotV1(1,"seryeong","seryeong.action.idle.v1",0,"east",0,0);Assert.That(CostumePresentationServiceV1.TrySwap(c,current,proposed,s,out _),Is.EqualTo(CostumeBindingRejection.None));var forged=new CostumePresentationBindingV1("seryeong",b.CostumeId,b.PortraitSetId,H,b.GameplaySetId,H,"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",1,1,new[]{"seryeong.action.idle.v1"});Assert.That(CostumePresentationServiceV1.TrySwap(c,current,forged,s,out _),Is.EqualTo(CostumeBindingRejection.HashMismatch));} } }
